INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Double Word immer 32 Bit groß?', 2, '[{"text": "Ja", "correct": true, "because": "Standard in vielen Systemen"}, {"text": "Nein", "correct": false, "because": "Kontextabhängig, meist 32 Bit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Double Word in der Programmierung?', 3, '[{"text": "Datengröße definieren", "correct": true, "because": "Speicherzuweisung"}, {"text": "Netzwerkpakete verschlüsseln", "correct": false, "because": "Andere Funktion"}, {"text": "Grafik rendern", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein Double Word?', 5, '[{"text": "32 Bit", "correct": true, "because": "Typische Größe"}, {"text": "4 Byte", "correct": true, "because": "32 Bit = 4 Byte"}, {"text": "8 Bit", "correct": false, "because": "Das ist ein Byte"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Double Word ist doppelt so groß wie ein Word. b) Es ist immer 64 Bit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "64 Bit ist QWORD"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Double Word?', 4, '[{"text": "Bitanzahl", "correct": false, "because": "Definiert Größe"}, {"text": "Speicheradresse", "correct": false, "because": "Zuweisung wichtig"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Double Word in 16-Bit-Systemen 32 Bit hat?', 2, '[{"text": "Ja", "correct": true, "because": "Doppelte Word-Größe"}, {"text": "Nein", "correct": false, "because": "Standard bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Größe hat ein Double Word in einem 32-Bit-System?', 3, '[{"text": "32 Bit", "correct": true, "because": "Doppelte Word-Größe von 16 Bit"}, {"text": "64 Bit", "correct": false, "because": "Das ist QWORD"}, {"text": "16 Bit", "correct": false, "because": "Nur ein Word"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Double Word?', 5, '[{"text": "Größere Datenmengen speichern", "correct": true, "because": "32 Bit Kapazität"}, {"text": "Effiziente Verarbeitung", "correct": true, "because": "Passend für CPU"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Nicht Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Double Word ist 4 Byte groß. b) Es ist nur für 64-Bit-Systeme. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Systemunabhängig 32 Bit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Double Word?', 4, '[{"text": "Speicherplatz", "correct": false, "because": "32 Bit nötig"}, {"text": "Prozessorunterstützung", "correct": false, "because": "Verarbeitung"}, {"text": "Physische Größe", "correct": true, "because": "Logisches Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Double Word dasselbe wie ein Byte?', 2, '[{"text": "Nein", "correct": true, "because": "Byte ist 8 Bit"}, {"text": "Ja", "correct": false, "because": "Double Word ist 32 Bit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Systeme nutzen Double Words?', 4, '[{"text": "32-Bit-Systeme", "correct": true, "because": "Standardgröße"}, {"text": "64-Bit-Systeme", "correct": true, "because": "Auch kompatibel"}, {"text": "Analogsysteme", "correct": false, "because": "Digitaler Begriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Double Word nur für Speicher ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Register"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Double Word?', 3, '[{"text": "Bitgröße", "correct": true, "because": "Definiert Kapazität"}, {"text": "Farbe", "correct": false, "because": "Irrelevant"}, {"text": "Gewicht", "correct": false, "because": "Kein physischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Double Word hat 32 Bit. b) Es ist kleiner als ein Word.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Doppelt so groß"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Begriffe sind mit Double Word verwandt?', 5, '[{"text": "Word", "correct": true, "because": "16 Bit"}, {"text": "QWORD", "correct": true, "because": "64 Bit"}, {"text": "Bitrate", "correct": false, "because": "Netzwerkbegriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Double Word unwichtig?', 3, '[{"text": "Speicherzuweisung", "correct": false, "because": "Grundlage"}, {"text": "Bitanzahl", "correct": false, "because": "Definiert Größe"}, {"text": "Verpackung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Double Word größer als ein QWORD?', 3, '[{"text": "Nein", "correct": true, "because": "QWORD ist 64 Bit"}, {"text": "Ja", "correct": false, "because": "Double Word ist 32 Bit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Double Word in Registern genutzt wird?', 2, '[{"text": "Ja", "correct": true, "because": "CPU-Verarbeitung"}, {"text": "Nein", "correct": false, "because": "Registeranwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für ein Double Word zentral?', 4, '[{"text": "32-Bit-Größe", "correct": true, "because": "Standarddefinition"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Nicht Funktion"}, {"text": "Physische Form", "correct": false, "because": "Logisches Konzept"}]');
